void CBladeEffect::initializeEffect(const SferaEffectInitializeContext& context) {
    if (!context.visible || context.spatial_frames.empty() || render_slot_budget + g_sfera_effect_manager.render_slot_count >= 10000u) return;
    const auto& input = context.spatial_frames.front();
    if (!anchor_initialized) {
        anchor = input;
        anchor_initialized = true;
    }
    const SferaVec3F reference = g_sfera_world_objects.referencePosition();
    SferaEffectRenderSlot* slot = g_sfera_effect_manager.acquireRenderSlot();
    if (slot == nullptr) return;
    progress += 0.05f;
    if (progress > 1.0f) progress = 1.0f;
    std::uint32_t alpha = 255u;
    if (progress > 0.8f) alpha = std::trunc((1.0f - progress) * 1275.0f);
    slot->resource_id = resource_id;
    slot->self_illumination = 255u;
    slot->additive = true;
    slot->custom_uv = true;
    for (std::size_t vertex = 0u; vertex < 4u; ++vertex) {
        slot->color[0][vertex] = 255u;
        slot->color[1][vertex] = 255u;
        slot->color[2][vertex] = 255u;
        slot->color[3][vertex] = alpha;
    }
    const SferaVec3F path = vec_sub(input, anchor);
    const SferaVec3F end = vec_add(anchor, vec_scale(path, progress));
    const SferaVec3F direction = vec_normalized(vec_sub(anchor, end));
    const SferaVec3F back = vec_sub(end, vec_scale(direction, 0.5f));
    const SferaVec3F back_width = vec_scale(vec_normalized(vec_cross(vec_sub(back, reference), vec_sub(back, end))), 0.8f);
    const SferaVec3F end_width = vec_scale(vec_normalized(vec_cross(vec_sub(end, reference), vec_sub(back, end))), 0.8f);
    slot->position[0] = vec_add(back, back_width);
    slot->position[1] = vec_sub(back, back_width);
    slot->position[2] = vec_sub(end, end_width);
    slot->position[3] = vec_add(end, end_width);
    slot->uv[0][0] = 0.0f;
    slot->uv[0][1] = 0.0f;
    slot->uv[1][0] = 1.0f;
    slot->uv[1][1] = progress;
    slot->uv[2][0] = 1.0f;
    slot->uv[2][1] = 1.0f;
    slot->uv[3][0] = 0.0f;
    slot->uv[3][1] = progress;
}

